# Validate inputs
if not (isinstance(logp_with_result, np.ndarray) and isinstance(logp_call_only, np.ndarray) and isinstance(logp_no_call, np.ndarray)):
    raise ValueError("Inputs must be numpy arrays")
if logp_with_result.ndim != 2 or logp_call_only.ndim != 2 or logp_no_call.ndim != 2:
    raise ValueError("Input matrices must be 2D")
if logp_with_result.shape != logp_call_only.shape or logp_with_result.shape != logp_no_call.shape:
    raise ValueError("Input matrices must have the same shape")
if logp_with_result.shape[0] == 0 or logp_with_result.shape[1] == 0:
    raise ValueError("Input matrices cannot be empty")
if not np.all(np.isfinite(logp_with_result)) or not np.all(np.isfinite(logp_call_only)) or not np.all(np.isfinite(logp_no_call)):
    raise ValueError("Input matrices must contain finite values")
if np.any(logp_with_result > 0) or np.any(logp_call_only > 0) or np.any(logp_no_call > 0):
    raise ValueError("Input matrices must contain nonpositive values")
if isinstance(tau_filter, bool):
    raise ValueError("tau_filter cannot be a boolean")
if not isinstance(tau_filter, (int, float)) or not np.isfinite(tau_filter) or tau_filter < 0:
    raise ValueError("tau_filter must be a finite nonnegative number")
# Compute margins and mask
improvement_over_no_call = np.sum(logp_with_result - logp_no_call, axis=1)
improvement_over_call_only = np.sum(logp_with_result - logp_call_only, axis=1)
keep_mask = (improvement_over_no_call > tau_filter) & (improvement_over_call_only > 0)
margins = improvement_over_no_call
return keep_mask, margins
